const path = items[0].json.filePath.toLowerCase();
let department = 'general';
let access_level = 'internal';
if (path.includes('/finance/')) department = 'finance';
if (path.includes('/engineering/')) department = 'engineering';
if (path.includes('/hr/')) department = 'hr';
if (path.includes('confidential')) access_level = 'confidential';
if (path.includes('public')) access_level = 'public';
items[0].json.department = department;
items[0].json.access_level = access_level;
return items;
